import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();Q=np.array([0.,1.,0.,0.]);
well=np.array([-.1604,.1802,.023]); start=np.array([.0135925-.050,-.1356-.012,.014]); end=start+np.array([0,-.070,0])
obs=r.get_obs(cameras=[],video='none'); cur=np.array(obs.meta['proprio']['now'][7:10]); quat=np.array(obs.meta['proprio']['now'][10:14])
# move through waypoint with high clearance; segment steps 2mm at 50ms
pts=[np.array([0.,0.,.108]),[well[0],well[1],.070],well,[well[0],well[1],.070],[start[0],start[1],.070],start,end,[end[0],end[1],.070]]
rows=[]
for j,p in enumerate(pts):
 p=np.asarray(p,float)
 d=np.linalg.norm(p-cur); n=max(1,int(np.ceil(d/.002)))
 for k in range(1,n+1): rows.append([*(cur+(p-cur)*k/n),*Q])
 if j==2:
  for _ in range(6): rows.append([*p,*Q])
 if j==5:
  for _ in range(6): rows.append([*p,*Q])
 cur=p
# settle at end above paper
for _ in range(8): rows.append([*cur,*Q])
res=r.submit('ee_pose',np.array(rows,np.float32),dt=.05,cameras=['practice_cam'],video='both',video_fps=10,note='practice width probe z=14mm')
res.save('/app/output/probe2_run')
print('rows',len(rows),'final',np.array(res.meta['proprio']['now'])[7:14], 'stopped',res.stopped)
